#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 10000

int main() {
    char s[MAX_SIZE];
    gets(s);

    int isNegative = 0;

    char negative[MAX_SIZE];
    int negative_size = 0;

    long long ans = 0;
    int i = 0;
    while (s[i] != '\0') {
        char c = s[i];

        if (c >= '0' && c <= '9') {
            if (isNegative) {
                negative[negative_size++] = c;
            } else {
                ans += c - '0';
            }
        } else {
            if (isNegative && negative_size > 0) {
                ans -= atol(negative);
                memset(negative, '\0', MAX_SIZE);
                negative_size = 0;
            }

            isNegative = c == '-';
        }

        i++;
    }

    if (negative_size > 0) {
        ans -= atol(negative);
    }

    printf("%lld\n", ans);

    return 0;
}
